// Characterization tests: pin current client-visible behavior, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 2.5, tv: 80, pen: 0.99, gold: 100 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('creates an order: 201, JSON, string id, echoed items, total', async () => {
  const res = await post({ items: [{ sku: 'apple', qty: 4 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, [{ sku: 'apple', qty: 4 }])
  assert.equal(order.total, 10)
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums multiple items', async () => {
  const order = await (await post({ items: [{ sku: 'apple', qty: 2 }, { sku: 'tv', qty: 0 }, { sku: 'apple', qty: 2 }] })).json()
  assert.equal(order.total, 10)
})

test('total is floored to a whole number', async () => {
  const order = await (await post({ items: [{ sku: 'pen', qty: 3 }] })).json() // 2.97
  assert.equal(order.total, 2)
})

test('no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'gold', qty: 1 }] })).json()
  assert.equal(order.total, 100)
})

test('10% discount above 100, then floored', async () => {
  const order = await (await post({ items: [{ sku: 'tv', qty: 2 }] })).json() // 160 -> 144
  assert.equal(order.total, 144)
  const o2 = await (await post({ items: [{ sku: 'gold', qty: 1 }, { sku: 'pen', qty: 2 }] })).json() // 101.98 -> 91.782
  assert.equal(o2.total, 91)
})

test('unknown sku yields a null total (NaN serialized) but still 201', async () => {
  const res = await post({ items: [{ sku: 'nope', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('rejects bad bodies with 400 and error message', async () => {
  const cases = [{}, { items: [] }, { items: 'x' }, null]
  for (const body of cases) {
    const res = await post(body)
    assert.equal(res.status, 400, JSON.stringify(body))
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  const bad = await post(undefined, '{not json')
  assert.equal(bad.status, 400)
  assert.deepEqual(await bad.json(), { error: 'items required' })
})

test('GET returns a previously created order', async () => {
  const created = await (await post({ items: [{ sku: 'tv', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with error body (not 404)', async () => {
  const res = await fetch(`${base}/orders/99999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 "no route"', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['PUT', '/orders/1'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/x']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
